const slot=(src,label,cls='',fallback='')=>`<div class="image-slot ${cls}" data-image="${src}"><img src="${src}" alt="${label}" loading="lazy" ${fallback?`data-fallback="${fallback}"`:''} onerror="handleImageError(this)"><span class="slot-label"><span>${label}</span><small>Project image coming soon</small></span></div>`;
function applyProjectImageColor(id,img){
 if(!img?.naturalWidth)return;
 try{
  const canvas=document.createElement('canvas'),size=48,ctx=canvas.getContext('2d',{willReadFrequently:true});canvas.width=size;canvas.height=size;ctx.drawImage(img,0,0,size,size);
  const pixels=ctx.getImageData(0,0,size,size).data,buckets=new Map();
  for(let y=0;y<size;y++)for(let x=0;x<size;x++){
   // Sample the screen's corner background areas. These are usually the broad
   // canvas colour in a UI mockup, while the centre contains photos and controls.
   const inBackgroundCorner=(x<size*.18||x>size*.82)&&(y>size*.08&&y<size*.3);
   if(!inBackgroundCorner)continue;
   const i=(y*size+x)*4,r=pixels[i],g=pixels[i+1],b=pixels[i+2];if(pixels[i+3]<200)continue;
   const brightness=(r+g+b)/3;
   if(brightness<28||brightness>248)continue;
   const key=[r,g,b].map(value=>Math.round(value/24)*24).join(',');buckets.set(key,(buckets.get(key)||0)+1);
  }
  const dominant=[...buckets.entries()].sort((a,b)=>b[1]-a[1])[0]?.[0];if(!dominant)return;
  const [r,g,b]=dominant.split(',').map(value=>Math.min(255,Number(value)));const color=`rgb(${r} ${g} ${b})`;
  const card=document.querySelector(`#project-grid [data-project="${id}"]`);if(card){card.style.setProperty('--project-image-color',color);card.setAttribute('data-image-palette','true')}
  const hero=document.querySelector('#project-content .case-hero');if(hero&&hero.dataset.project===id){hero.style.setProperty('--project-image-color',color);hero.setAttribute('data-image-palette','true')}
 }catch(error){/* Keep the project's original palette when the browser cannot sample the image. */}
}
function watchProjectImage(id,img){const update=()=>applyProjectImageColor(id,img);if(img.complete)update();else img.addEventListener('load',update,{once:true})}
