function renderGroupedScreens(id,screens,groups){return groups.map(group=>`<section class="screen-group"><header><p class="eyebrow">${group.title}</p><p>${group.description}</p></header><div class="screen-gallery">${screens.slice(group.from,group.to).map((screen,index)=>{const n=group.from+index+1;const filename=`${id}-screen-${String(n).padStart(2,'0')}.jpg`;return `<figure class="screen-card"><figcaption><span>${String(n).padStart(2,'0')}</span><b>${screen.title}</b></figcaption>${slot(`assets/projects/${filename}`,screen.title,'screen-slot')}<p class="screen-description">${screen.description}</p></figure>`}).join('')}</div></section>`).join('')}
function openProject(id){
 const p=projects.find(x=>x.id===id);if(!p)return;
  const queue=id==='queueless',mama=id==='mamacare',tasty=id==='tasty-dishes',findhouse=id==='findhouse',aiStylish=id==='ai-stylish',grocery=id==='grocery-store';
  const grouped=queue||mama||tasty||findhouse||aiStylish||grocery;
  const screens=queue?queueScreens:mama?mamacareScreens:tasty?tastyScreens:findhouse?findhouseScreens:aiStylish?aiStylishScreens:grocery?groceryScreens:null;
  const groups=queue?queueGroups:mama?mamacareGroups:tasty?tastyGroups:findhouse?findhouseGroups:aiStylish?aiStylishGroups:grocery?groceryGroups:null;
 const gallery=screens?renderGroupedScreens(id,screens,groups):p.screens.map((s,i)=>`<figure class="screen-card"><figcaption><span>${String(i+1).padStart(2,'0')}</span><b>${s}</b></figcaption>${slot(`assets/projects/${p.id}-screen-${String(i+1).padStart(2,'0')}.jpg`,s,'screen-slot')}<p class="screen-description">A key screen in the ${p.name} experience, designed to make this step clear and easy to complete.</p></figure>`).join('');
  const challenge=queue?'Waiting without a reliable estimate makes it hard to plan a visit. QueueLess brings branch discovery, service requirements, virtual queue updates and appointment confirmation into one mobile journey.':mama?'Pregnancy and early newborn care bring appointments, changing needs and many questions. MamaCare gathers week-by-week guidance, care planning and preparation into one supportive companion.':tasty?'Finding local food should make it easy to compare what is available and understand an order before committing. Tasty Dishes connects menu discovery, useful meal details, search and basket review in one mobile journey.':findhouse?'Finding a home can involve uncertainty about listings, locations and who to trust. FindHouse brings verified homes, map-based discovery, useful property details and direct agent contact into one place.':aiStylish?'Getting dressed can be difficult when it is hard to picture combinations, plan for changing weather or remember what is already in the wardrobe. AI Stylish brings try-on, outfit suggestions and wardrobe planning together.':grocery?'Finding fresh groceries and everyday essentials is easier when shoppers can quickly see what is available, search products and browse familiar categories. Grocery Store brings those discovery steps together in a simple mobile experience.':`${p.desc} The work focuses on clear information, useful next steps and an experience that respects people’s time and context.`;
  const response=queue?'The design makes wait information visible before joining, explains service requirements up front, and gives people a ticket they can follow while they wait. Appointment confirmation keeps the date, time, branch and service together.':mama?'The design keeps the current stage and next useful action easy to find, while bringing appointments, learning and health notes into an organized experience that can continue into newborn care.':tasty?'The screens foreground food imagery and clear prices, let customers search and compare meals, and make the selected dishes and total easy to review in the basket.':findhouse?'Trust is supported through visible verification, neighborhood context, property information and a direct path to ask an agent about a viewing. Saved listings help people keep their options organized.':aiStylish?'The experience connects a digital try-on with practical outfit advice and a wardrobe calendar, helping members choose looks for the day and get more use from clothes they already own.':grocery?'A welcoming onboarding screen sets the promise, Home makes offers and popular products visible, and Categories gives shoppers a direct way to search and browse essentials.':'Reduce uncertainty at each step. Keep the most important information easy to scan, actions easy to understand and feedback visible as the experience moves forward.';
 const problemLabel=queue?'THE PROBLEM':mama?'THE CARE CHALLENGE':'THE OPPORTUNITY';
  const galleryLabel=queue?'THE QUEUELESS FLOW':mama?'THE MAMACARE JOURNEY':tasty?'THE TASTY DISHES JOURNEY':findhouse?'THE FINDHOUSE JOURNEY':aiStylish?'THE AI STYLISH JOURNEY':grocery?'THE GROCERY STORE JOURNEY':'SCREENS & FLOW';
 content.innerHTML=`<header class="case-hero ${p.color}" data-project="${p.id}"><p class="eyebrow">${p.type}</p><h2>${p.name}<br><em>${p.tag}</em></h2><p>${p.desc}</p><span class="case-role">${p.role}</span></header><section class="case-body">${['queueless','mamacare'].includes(p.id)?'<div class="sale-offer"><div><span class="sale-status">AVAILABLE FOR SALE</span><b>$100</b></div><a href="contact.html?purchase='+p.id+'">Message me to purchase <span>↗</span></a></div>':''}<div class="case-overview"><div><p class="eyebrow">${problemLabel}</p><h3>${p.stat}</h3></div><p>${challenge}</p></div><div class="case-columns"><div><p class="eyebrow">${grouped?'THE USER JOURNEY':'CORE USER FLOWS'}</p><ol class="flow-list">${p.flows.map((f,i)=>`<li><span>0${i+1}</span>${f}</li>`).join('')}</ol></div><div class="case-note"><p class="eyebrow">${grouped?'DESIGN RESPONSE':'DESIGN INTENT'}</p><p>${response}</p></div></div><div class="gallery-head"><div><p class="eyebrow">${galleryLabel}</p><h3>${grouped?'Important screens, grouped by task.':'Explore the experience.'}</h3></div></div>${grouped?gallery:`<section class="screen-group"><div class="screen-gallery">${gallery}</div></section>`}<a class="button button-dark case-contact" href="contact.html" onclick="document.querySelector('#project-dialog').close()">Talk about a project <span>↗</span></a></section>`;
 const cardPalette=grid?.querySelector(`[data-project="${p.id}"]`),hero=content.querySelector('.case-hero');
 if(cardPalette&&hero){const color=cardPalette.style.getPropertyValue('--project-image-color');if(color){hero.style.setProperty('--project-image-color',color);hero.setAttribute('data-image-palette','true')}}
 const heroImage=content.querySelector('.screen-card .screen-slot img');if(heroImage)watchProjectImage(p.id,heroImage);
 dialog.showModal();document.body.classList.add('dialog-open');
}
