// Reveal content as it enters the viewport; honor the visitor's reduced-motion preference.
if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver' in window){
 const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');revealObserver.unobserve(entry.target)}}),{threshold:.12});
 document.querySelectorAll('.section-heading,.about-heading,.about-copy,.approach-grid article,.contact-copy,.contact-form,.project-card').forEach((element,index)=>{element.classList.add('reveal-on-scroll');element.style.setProperty('--reveal-delay',`${(index%4)*75}ms`);revealObserver.observe(element)});
}

// Pricing cards take turns floating. A visitor can select one to pause the rotation.
const pricingCards=[...document.querySelectorAll('.pricing-grid article')];
if(pricingCards.length){
 let selectedByVisitor=false,activeIndex=0;
 const showPricingCard=index=>pricingCards.forEach((card,i)=>{const active=i===index;card.classList.toggle('is-floating',active);card.setAttribute('aria-pressed',String(active))});
 pricingCards.forEach((card,index)=>{
  card.setAttribute('role','button');card.setAttribute('tabindex','0');
  card.addEventListener('click',()=>{selectedByVisitor=true;activeIndex=index;showPricingCard(index)});
  card.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();selectedByVisitor=true;activeIndex=index;showPricingCard(index)}});
 });
 const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 if(!reducedMotion){showPricingCard(activeIndex);window.setInterval(()=>{if(!selectedByVisitor){activeIndex=(activeIndex+1)%pricingCards.length;showPricingCard(activeIndex)}},3200)}
}

// Type and fade the About introduction, restarting in the selected language.
const aboutIntro=document.querySelector('.about-intro-typewriter,.home-intro-typewriter');
if(aboutIntro){
 const typedText=aboutIntro.querySelector('.typewriter-text');
 const englishIntro=typedText.textContent;
 const frenchIntro=typedText.dataset.fr;
 const emphasizedText=typedText.dataset.emphasis||'';
 let typeTimer=0;
 const paintIntro=text=>{
  if(!emphasizedText){typedText.textContent=text;return}
  const start=text.indexOf(emphasizedText);
  if(start<0){typedText.textContent=text;return}
  typedText.replaceChildren(document.createTextNode(text.slice(0,start)));
  const emphasis=document.createElement('strong');emphasis.textContent=emphasizedText;
  typedText.append(emphasis,document.createTextNode(text.slice(start+emphasizedText.length)));
 };
 const writeIntro=()=>{
  window.clearTimeout(typeTimer);
  const fullIntro=document.documentElement.lang==='fr'?frenchIntro:englishIntro;
  const letters=Array.from(fullIntro);
  paintIntro('');typedText.classList.remove('is-fading');aboutIntro.setAttribute('aria-label',fullIntro);
  let position=0;
  const typeNext=()=>{
   if(position<letters.length){paintIntro(letters.slice(0,position+1).join(''));position++;typeTimer=window.setTimeout(typeNext,38);return}
   typeTimer=window.setTimeout(()=>{
    typedText.classList.add('is-fading');
    typeTimer=window.setTimeout(writeIntro,520);
   },1900);
  };
  typeNext();
 };
 document.addEventListener('portfolio-language-change',writeIntro);
 typeTimer=window.setTimeout(writeIntro,250);
}
// Keep the requested portrait float visible in browsers with reduced-motion preferences.
const aboutPortrait=document.querySelector('.about-hero .about-profile');
if(aboutPortrait&&typeof aboutPortrait.animate==='function'){
 aboutPortrait.animate([{transform:'translateY(0)'},{transform:'translateY(-14px)'},{transform:'translateY(0)'}],{duration:2800,easing:'ease-in-out',iterations:Infinity});
}
